<template><div class="flex min-h-screen items-center justify-center bg-bg-primary p-4 text-text-primary"><div class="w-full max-w-md rounded-lg border border-border-secondary bg-bg-secondary p-8 text-center"><AppSpinner v-if="loading" :label="common.loading" /><template v-else><CircleCheck v-if="completed" class="mx-auto text-success" :size="56" /><CircleAlert v-else class="mx-auto text-warning" :size="56" /><h1 class="mt-4 text-xl font-black">{{ completed ? locale.completed : locale.pending }}</h1><p class="mt-2 text-sm text-text-tertiary">{{ locale.paymentHint }}</p><NuxtLink to="/payment" class="mt-6 inline-flex rounded-lg bg-primary px-5 py-2.5 text-sm font-bold text-white">{{ locale.orders }}</NuxtLink></template></div></div></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { CircleAlert, CircleCheck } from '@lucide/vue'; import AppSpinner from '~/components/UI/Common/AppSpinner.vue'; import { useLocale } from '~/utils/locale'
const sections = useLocale(); const locale = computed(() => sections.payment.value); const common = computed(() => sections.common.value); const route = useRoute(); const loading = ref(true); const completed = ref(false)
onMounted(async () => { const id = String(route.query.order || ''); if (id) { try { const order = await $fetch(`/api/payment/orders/${id}/verify`, { method: 'POST' }); completed.value = order.status === 'COMPLETED' } catch {} } loading.value = false })
</script>
